import { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowDownLeft,
  ArrowLeftRight,
  ArrowUpRight,
  Banknote,
  Boxes,
  ChartNoAxesCombined,
  Check,
  ChevronDown,
  Cloud,
  CloudDownload,
  CloudUpload,
  FileClock,
  FileDown,
  FileJson,
  FileText,
  LayoutDashboard,
  LockKeyhole,
  Menu,
  Plus,
  Percent,
  RefreshCw,
  Tags,
  Search,
  Settings2,
  ShieldCheck,
  Upload,
  Users,
  WalletCards,
  X,
} from "lucide-react";
import {
  AppState,
  CheckStatus,
  PageId,
  TransactionType,
  appendAudit,
  calculateMetrics,
  createId,
  exportPayload,
  formatDate,
  formatMoney,
  formatNumber,
  importPayload,
  loadState,
  navItems,
  personName,
  saveState,
  todayJalali,
  transactionLabel,
  calculateLateProfit,
  allocateCheckFIFO,
  applyCheckFIFO,
  PERSON_TYPES,
  UNIT_OPTIONS,
} from "@/lib/accounting";

const iconMap = { "layout-dashboard": LayoutDashboard, "file-text": FileText, "arrow-left-right": ArrowLeftRight, users: Users, boxes: Boxes, "file-clock": FileClock, "chart-no-axes-combined": ChartNoAxesCombined, "cloud-cog": Cloud, tags: Tags, percent: Percent, "lock-keyhole": LockKeyhole } as const;

function Icon({ name, size = 18 }: { name: keyof typeof iconMap; size?: number }) {
  const Component = iconMap[name];
  return <Component size={size} strokeWidth={1.8} />;
}

function statusClass(status: string) {
  if (["وصول شده", "ثبت شده", "تودیع شده"].includes(status)) return "status-success";
  if (["برگشتی", "باطل"].includes(status)) return "status-danger";
  return "status-warning";
}

function EmptyState({ title, description, onAction, actionLabel }: { title: string; description: string; onAction?: () => void; actionLabel?: string }) {
  return <div className="empty-state"><div className="empty-icon"><FileJson size={22} /></div><strong>{title}</strong><p>{description}</p>{onAction && actionLabel && <button className="button button-primary button-small" onClick={onAction}><Plus size={16} />{actionLabel}</button>}</div>;
}

export default function Home() {
  const [state, setState] = useState<AppState>(() => loadState());
  const [activePage, setActivePage] = useState<PageId>("dashboard");
  const [mobileNav, setMobileNav] = useState(false);
  const [quickOpen, setQuickOpen] = useState(false);
  const [notice, setNotice] = useState("");
  const fileInput = useRef<HTMLInputElement>(null);

  useEffect(() => { localStorage.setItem("accounting-workshop-pwa:v1", JSON.stringify(state)); }, [state]);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(""), 3600); return () => window.clearTimeout(timer); }, [notice]);

  const metrics = useMemo(() => calculateMetrics(state), [state]);
  const activeNav = navItems.find((item) => item.id === activePage) || navItems[0];

  function updateState(next: AppState, message: string) {
    setState(saveState(appendAudit(next, "UPDATE", message)));
    setNotice(message);
  }

  function handleExport() {
    const blob = new Blob([exportPayload(state)], { type: "application/json;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a"); link.href = url; link.download = `backup-accounting-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url);
    setNotice("فایل پشتیبان با موفقیت آماده شد");
  }

  function handleImport(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = () => { try { const next = importPayload(String(reader.result)); setState(saveState(appendAudit(next, "RESTORE", `بازیابی از ${file.name}`))); setNotice("بازیابی با موفقیت انجام شد"); } catch (error) { setNotice(error instanceof Error ? error.message : "خواندن فایل ناموفق بود"); } };
    reader.readAsText(file); event.target.value = "";
  }

  function addTransaction(input: { type: TransactionType; amount: number; partyId?: string; note: string; date: string }) {
    const next = { ...state, transactions: [{ id: createId("txn"), status: "ثبت شده" as const, ...input }, ...state.transactions] };
    updateState(next, `ثبت ${transactionLabel(input.type)} جدید`); setQuickOpen(false);
  }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? "sidebar-open" : ""}`}>
      <div className="brand"><div className="brand-mark"><span>ک</span></div><div><strong>کارگاه</strong><small>دفتر هوشمند</small></div><button className="mobile-close" onClick={() => setMobileNav(false)}><X size={18} /></button></div>
      <div className="workspace-switch"><div className="workspace-avatar">ک</div><div><strong>{state.settings.businessName}</strong><small>نسخه محلی فعال</small></div><ChevronDown size={15} /></div>
      <div className="nav-label">منوی اصلی</div>
      <nav className="main-nav">{navItems.map((item) => <button key={item.id} className={`nav-item ${activePage === item.id ? "active" : ""}`} onClick={() => { setActivePage(item.id); setMobileNav(false); }}><span className="nav-icon"><Icon name={item.icon as keyof typeof iconMap} size={18} /></span><span><strong>{item.label}</strong><small>{item.caption}</small></span>{item.id === "checks" && state.checks.filter((check) => check.status === "برگشتی").length > 0 && <b className="nav-count">{state.checks.filter((check) => check.status === "برگشتی").length}</b>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="offline-card"><div className="online-dot" /><div><strong>ذخیره‌سازی محلی</strong><small>اطلاعات روی همین دستگاه</small></div></div><button className="settings-link" onClick={() => setActivePage("backup")}><Settings2 size={17} />تنظیمات برنامه</button></div>
    </aside>
    {mobileNav && <button className="sidebar-backdrop" onClick={() => setMobileNav(false)} aria-label="بستن منو" />}
    <main className="main-area">
      <header className="topbar"><div className="topbar-title"><button className="mobile-menu" onClick={() => setMobileNav(true)}><Menu size={21} /></button><div><div className="eyebrow">{todayJalali()}</div><h1>{activeNav.label}</h1></div></div><div className="topbar-actions"><div className="save-indicator"><span /><span>ذخیره خودکار فعال</span></div><button className="icon-button" title="پشتیبان‌گیری" onClick={handleExport}><FileDown size={18} /></button><button className="user-chip"><span className="user-avatar">م</span><span className="user-name">مدیر کارگاه</span><ChevronDown size={14} /></button></div></header>
      <div className="content-wrap">
        {activePage === "invoices" && <Invoices state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "dashboard" && <Dashboard state={state} metrics={metrics} onQuick={() => setQuickOpen(true)} onNavigate={setActivePage} />}
        {activePage === "transactions" && <Transactions state={state} onQuick={() => setQuickOpen(true)} />}
        {activePage === "people" && <People state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "inventory" && <Inventory state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "prices" && <Prices state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "paymentRules" && <PaymentRules state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "checks" && <Checks state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "monthClose" && <MonthClose state={state} onSave={(next, msg) => updateState(next, msg)} />}
        {activePage === "reports" && <Reports state={state} metrics={metrics} />}
        {activePage === "backup" && <BackupPage state={state} onExport={handleExport} onImport={() => fileInput.current?.click()} />}
      </div>
    </main>
    <input ref={fileInput} type="file" accept="application/json,.json" hidden onChange={handleImport} />
    {quickOpen && <QuickAdd onClose={() => setQuickOpen(false)} people={state.people} onSave={addTransaction} />}
    {notice && <div className="toast"><Check size={17} />{notice}</div>}
  </div>;
}

function Dashboard({ state, metrics, onQuick, onNavigate }: { state: AppState; metrics: ReturnType<typeof calculateMetrics>; onQuick: () => void; onNavigate: (page: PageId) => void }) {
  const recent = state.transactions.slice(0, 5);
  return <div className="page-stack page-enter"><section className="welcome-row"><div><div className="eyebrow accent-eyebrow">مرکز کنترل کارگاه</div><h2>خلاصهٔ امروز، <em>روشن و ساده</em></h2><p>اطلاعات مالی و عملیاتی را یک‌جا ببینید و با خیال راحت جلو بروید.</p></div><button className="button button-primary" onClick={onQuick}><Plus size={18} />ثبت عملیات جدید</button></section>
    <section className="metric-grid"><MetricCard label="دریافت این دوره" value={formatMoney(metrics.receipts, state.settings.currency)} helper="نقدینگی واردشده" icon={<ArrowDownLeft size={20} />} tone="mint" /><MetricCard label="پرداخت و هزینه" value={formatMoney(metrics.payments, state.settings.currency)} helper="خروجی ثبت‌شده" icon={<ArrowUpRight size={20} />} tone="rose" /><MetricCard label="مانده خالص" value={formatMoney(metrics.balance, state.settings.currency)} helper="دریافت منهای پرداخت" icon={<WalletCards size={20} />} tone="indigo" /><MetricCard label="چک‌های در جریان" value={formatMoney(metrics.outstandingChecks, state.settings.currency)} helper={`${formatNumber(state.checks.length)} فقره ثبت‌شده`} icon={<FileClock size={20} />} tone="amber" /></section>
    <section className="dashboard-grid"><div className="panel large-panel"><div className="panel-heading"><div><span className="section-kicker">گردش مالی</span><h3>آخرین عملیات</h3></div><button className="text-button" onClick={() => onNavigate("transactions")}>مشاهده همه <ArrowLeftRight size={15} /></button></div>{recent.length ? <div className="activity-list">{recent.map((item) => <ActivityRow key={item.id} item={item} state={state} />)}</div> : <EmptyState title="هنوز عملیاتی ثبت نشده" description="اولین فروش، دریافت یا هزینهٔ کارگاه را ثبت کنید تا گردش مالی اینجا نمایش داده شود." onAction={onQuick} actionLabel="ثبت اولین عملیات" />}</div><div className="panel action-panel"><div className="panel-heading"><div><span className="section-kicker">دسترسی سریع</span><h3>کارهای روزانه</h3></div><span className="panel-dot" /></div><div className="quick-actions"><QuickAction icon={<ArrowDownLeft />} label="ثبت دریافت" tone="mint" onClick={onQuick} /><QuickAction icon={<ArrowUpRight />} label="ثبت پرداخت" tone="rose" onClick={onQuick} /><QuickAction icon={<Users />} label="طرف حساب جدید" tone="violet" onClick={() => onNavigate("people")} /><QuickAction icon={<Boxes />} label="بررسی موجودی" tone="amber" onClick={() => onNavigate("inventory")} /></div><div className="privacy-note"><ShieldCheck size={17} /><span><strong>داده‌ها در امان‌اند</strong><small>ذخیره خودکار روی دستگاه شما فعال است.</small></span></div></div></section>
    <section className="bottom-grid"><div className="mini-panel"><div className="mini-panel-title"><span className="mini-icon mint"><Users size={17} /></span><span><strong>طرف حساب‌ها</strong><small>دفتر ارتباطات مالی</small></span></div><strong className="big-number">{formatNumber(state.people.length)}</strong><button className="under-button" onClick={() => onNavigate("people")}>مدیریت طرف حساب‌ها <ArrowLeftRight size={14} /></button></div><div className="mini-panel"><div className="mini-panel-title"><span className="mini-icon amber"><Boxes size={17} /></span><span><strong>موجودی کالا</strong><small>کالاهای قابل پیگیری</small></span></div><strong className="big-number">{formatNumber(state.products.length)}</strong><button className="under-button" onClick={() => onNavigate("inventory")}>مشاهده انبار <ArrowLeftRight size={14} /></button></div><div className="mini-panel"><div className="mini-panel-title"><span className="mini-icon violet"><Banknote size={17} /></span><span><strong>حساب‌های نقدی</strong><small>بانک و صندوق</small></span></div><strong className="big-number">{formatMoney(state.accounts.reduce((sum, account) => sum + account.balance, 0), state.settings.currency)}</strong><button className="under-button" onClick={() => onNavigate("reports")}>گزارش نقدینگی <ArrowLeftRight size={14} /></button></div></section>
  </div>;
}

function MetricCard({ label, value, helper, icon, tone }: { label: string; value: string; helper: string; icon: React.ReactNode; tone: string }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small>{helper}</small></div><div className="metric-spark"><span /><span /><span /><span /><span /></div></div>; }
function QuickAction({ icon, label, tone, onClick }: { icon: React.ReactNode; label: string; tone: string; onClick: () => void }) { return <button className="quick-action" onClick={onClick}><span className={`quick-icon ${tone}`}>{icon}</span><span>{label}</span><ArrowLeftRight size={14} /></button>; }
function ActivityRow({ item, state }: { item: AppState["transactions"][number]; state: AppState }) { const incoming = ["دریافت", "درآمد"].includes(item.type); return <div className="activity-row"><span className={`activity-icon ${incoming ? "mint" : "rose"}`}>{incoming ? <ArrowDownLeft size={17} /> : <ArrowUpRight size={17} />}</span><span className="activity-main"><strong>{transactionLabel(item.type)}</strong><small>{personName(state, item.partyId)} · {formatDate(item.date)}</small></span><strong className={incoming ? "amount-positive" : "amount-negative"}>{incoming ? "+" : "−"}{formatMoney(item.amount, state.settings.currency)}</strong><span className={`status-pill ${statusClass(item.status)}`}>{item.status}</span></div>; }

function Invoices({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [open, setOpen] = useState(false);
  const blankItem = { productId: "", quantity: "1", unitPrice: "" };
  const [form, setForm] = useState({ number: "", type: "فروش" as "فروش" | "خرید", date: todayJalali(), partyId: "", paymentRuleId: "", priceHistoryId: "", items: [blankItem], note: "" });
  const party = state.people.find((item) => item.id === form.partyId);
  const calculatedAmount = form.items.reduce((sum, item) => sum + (Number(item.quantity) || 0) * (Number(item.unitPrice.replace(/[^0-9.-]/g, "")) || 0), 0);
  function updateItem(index: number, patch: Partial<typeof blankItem>) { setForm({ ...form, items: form.items.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item) }); }
  function submit(event: React.FormEvent) { event.preventDefault(); if (!calculatedAmount) return; const items = form.items.map((row) => { const product = state.products.find((item) => item.id === row.productId); const quantity = Number(row.quantity) || 0; const unitPrice = Number(row.unitPrice.replace(/[^0-9.-]/g, "")) || 0; return { id: createId("invoice-item"), productId: row.productId || undefined, description: product?.name || "خدمت/کالای آزاد", quantity, unit: product?.unit || "عدد", unitPrice, total: quantity * unitPrice }; }); const invoice = { id: createId("invoice"), number: form.number.trim() || String(state.invoices.length + 1).padStart(4, "0"), type: form.type, date: form.date, partyId: form.partyId || undefined, paymentRuleId: form.paymentRuleId || party?.defaultPaymentRuleId || state.paymentRules.find((item) => item.active)?.id, priceHistoryId: form.priceHistoryId || undefined, items, allocations: [], amount: calculatedAmount, paidAmount: 0, status: "باز" as const, note: form.note }; const products = state.products.map((product) => { const movement = items.filter((item) => item.productId === product.id).reduce((sum, item) => sum + item.quantity, 0); if (!movement) return product; return { ...product, stock: product.stock + (form.type === "خرید" ? movement : -movement) }; }); onSave({ ...state, products, invoices: [invoice, ...state.invoices] }, form.type === "فروش" ? "فاکتور فروش ثبت شد و خروج کالا از انبار انجام شد" : "فاکتور خرید ثبت شد و ورود کالا به انبار انجام شد"); setOpen(false); setForm({ number: "", type: "فروش", date: todayJalali(), partyId: "", paymentRuleId: "", priceHistoryId: "", items: [blankItem], note: "" }); }
  return <div className="page-stack page-enter"><PageIntro kicker="مرکز اسناد" title="فاکتورها" description="چند ردیف کالا/خدمت را ثبت کنید؛ مبلغ کل و گردش موجودی خودکار محاسبه می‌شود." actionLabel="ثبت فاکتور" onAction={() => setOpen(true)} /><section className="metric-grid"><MetricCard label="فاکتورهای باز" value={formatNumber(state.invoices.filter((invoice) => invoice.status !== "تسویه شده").length)} helper="اسناد دارای مانده" icon={<FileText size={20} />} tone="amber" /><MetricCard label="مانده فاکتورها" value={formatMoney(state.invoices.reduce((sum, invoice) => sum + Math.max(0, invoice.amount - invoice.paidAmount), 0), state.settings.currency)} helper="مبلغ قابل وصول" icon={<WalletCards size={20} />} tone="rose" /><MetricCard label="فروش ثبت‌شده" value={formatMoney(state.invoices.filter((invoice) => invoice.type === "فروش").reduce((sum, invoice) => sum + invoice.amount, 0), state.settings.currency)} helper="قبل از تسویه" icon={<ArrowDownLeft size={20} />} tone="mint" /><MetricCard label="خرید ثبت‌شده" value={formatMoney(state.invoices.filter((invoice) => invoice.type === "خرید").reduce((sum, invoice) => sum + invoice.amount, 0), state.settings.currency)} helper="ورودی انبار" icon={<Boxes size={20} />} tone="indigo" /></section><div className="panel table-panel"><div className="panel-heading"><div><span className="section-kicker">دفتر فاکتور</span><h3>{formatNumber(state.invoices.length)} فاکتور</h3></div><span className="soft-tag">FIFO چک‌ها و ماندهٔ واقعی</span></div><div className="table-wrap"><table><thead><tr><th>شماره</th><th>تاریخ</th><th>طرف حساب</th><th>اقلام</th><th>مبلغ</th><th>تسویه</th><th>مانده</th><th>وضعیت</th></tr></thead><tbody>{state.invoices.length ? state.invoices.map((invoice) => <tr key={invoice.id}><td><strong>{invoice.number}</strong></td><td>{formatDate(invoice.date)}</td><td>{personName(state, invoice.partyId)}</td><td>{formatNumber(invoice.items.length)} قلم</td><td className="amount-cell">{formatMoney(invoice.amount, state.settings.currency)}</td><td>{formatMoney(invoice.paidAmount, state.settings.currency)}</td><td className="amount-cell">{formatMoney(Math.max(0, invoice.amount - invoice.paidAmount), state.settings.currency)}</td><td><span className={`status-pill ${invoice.status === "تسویه شده" ? "status-success" : "status-warning"}`}>{invoice.status}</span></td></tr>) : <tr><td colSpan={8}><EmptyState title="فاکتوری ثبت نشده" description="اولین فاکتور را با چند ردیف کالا ثبت کنید." onAction={() => setOpen(true)} actionLabel="ثبت فاکتور" /></td></tr>}</tbody></table></div></div>{open && <Dialog title="ثبت فاکتور چندردیفی" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label>شماره فاکتور<input value={form.number} onChange={(e) => setForm({ ...form, number: e.target.value })} /></label><label>نوع فاکتور<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as "فروش" | "خرید" })}><option>فروش</option><option>خرید</option></select></label><label>تاریخ فاکتور<input value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></label><label>طرف حساب<select value={form.partyId} onChange={(e) => setForm({ ...form, partyId: e.target.value, paymentRuleId: "" })}><option value="">بدون طرف حساب</option>{state.people.map((person) => <option value={person.id} key={person.id}>{person.name}</option>)}</select></label><label>شرایط پرداخت<select value={form.paymentRuleId || party?.defaultPaymentRuleId || ""} onChange={(e) => setForm({ ...form, paymentRuleId: e.target.value })}><option value="">پیش‌فرض طرف حساب/فعال</option>{state.paymentRules.map((rule) => <option value={rule.id} key={rule.id}>{rule.name}</option>)}</select></label><div className="full-field invoice-items-editor"><div className="tier-editor-head"><span>ریزاقلام فاکتور</span><button type="button" className="text-button" onClick={() => setForm({ ...form, items: [...form.items, blankItem] })}><Plus size={14} />افزودن ردیف</button></div>{form.items.map((row, index) => <div className="invoice-item-row" key={index}><select value={row.productId} onChange={(e) => { const product = state.products.find((item) => item.id === e.target.value); updateItem(index, { productId: e.target.value, unitPrice: product ? String(product.price) : row.unitPrice }); }}><option value="">کالا/خدمت آزاد</option>{state.products.map((product) => <option value={product.id} key={product.id}>{product.name}</option>)}</select><input inputMode="decimal" value={row.quantity} onChange={(e) => updateItem(index, { quantity: e.target.value })} placeholder="تعداد" /><input inputMode="numeric" value={row.unitPrice} onChange={(e) => updateItem(index, { unitPrice: e.target.value })} placeholder="قیمت واحد" />{form.items.length > 1 && <button type="button" className="icon-button" onClick={() => setForm({ ...form, items: form.items.filter((_, itemIndex) => itemIndex !== index) })}>×</button>}</div>)}</div><div className="panel invoice-total"><span>مبلغ کل فاکتور</span><strong>{formatMoney(calculatedAmount, state.settings.currency)}</strong></div><label className="full-field">توضیحات<input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} /></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره فاکتور</button></div></form></Dialog>}</div>;
}
function Transactions({ state, onQuick }: { state: AppState; onQuick: () => void }) { return <div className="page-stack page-enter"><PageIntro kicker="دفتر عملیات" title="عملیات مالی" description="فروش، خرید، دریافت، پرداخت و هزینه‌ها را در یک دفتر شفاف مدیریت کنید." actionLabel="ثبت عملیات" onAction={onQuick} /><div className="toolbar"><div className="search-box"><Search size={17} /><input placeholder="جست‌وجوی عملیات یا طرف حساب..." /></div><button className="filter-button">همه عملیات <ChevronDown size={15} /></button><button className="filter-button">این ماه <ChevronDown size={15} /></button></div><div className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>نوع عملیات</th><th>تاریخ</th><th>طرف حساب</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>{state.transactions.length ? state.transactions.map((item) => <tr key={item.id}><td><span className="table-type"><span className={`table-dot ${["دریافت", "درآمد"].includes(item.type) ? "mint" : "rose"}`} />{transactionLabel(item.type)}</span></td><td>{formatDate(item.date)}</td><td>{personName(state, item.partyId)}</td><td className="amount-cell">{formatMoney(item.amount, state.settings.currency)}</td><td><span className={`status-pill ${statusClass(item.status)}`}>{item.status}</span></td></tr>) : <tr><td colSpan={5}><EmptyState title="دفتر عملیات خالی است" description="هنوز رکوردی برای نمایش وجود ندارد." onAction={onQuick} actionLabel="ثبت عملیات" /></td></tr>}</tbody></table></div></div></div>; }

function People({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: "", roles: ["مشتری"] as AppState["people"][number]["roles"], phone: "", defaultPaymentRuleId: "" });
  function toggleRole(role: AppState["people"][number]["roles"][number]) { setForm({ ...form, roles: form.roles.includes(role) ? form.roles.filter((item) => item !== role) : [...form.roles, role] }); }
  function submit(event: React.FormEvent) { event.preventDefault(); if (!form.name.trim() || !form.roles.length) return; onSave({ ...state, people: [{ id: createId("person"), code: String(state.people.length + 1).padStart(3, "0"), name: form.name.trim(), type: form.roles[0], roles: form.roles, phone: form.phone, defaultPaymentRuleId: form.defaultPaymentRuleId || undefined, balance: 0 }, ...state.people] }, "طرف حساب با نقش‌های انتخاب‌شده ثبت شد"); setForm({ name: "", roles: ["مشتری"], phone: "", defaultPaymentRuleId: "" }); setOpen(false); }
  return <div className="page-stack page-enter"><PageIntro kicker="دفتر اشخاص" title="طرف حساب‌ها" description="یک نفر می‌تواند هم‌زمان مشتری، تأمین‌کننده، شریک یا هر نقش دیگری داشته باشد." actionLabel="افزودن طرف حساب" onAction={() => setOpen(true)} /><div className="panel table-panel"><div className="panel-heading"><div><span className="section-kicker">دفتر اشخاص</span><h3>{formatNumber(state.people.length)} رکورد</h3></div><div className="search-box compact"><Search size={16} /><input placeholder="جست‌وجو..." /></div></div><div className="table-wrap"><table><thead><tr><th>کد</th><th>نام</th><th>نقش‌ها</th><th>تلفن</th><th>مانده</th></tr></thead><tbody>{state.people.length ? state.people.map((person) => <tr key={person.id}><td className="muted-cell">{person.code}</td><td><strong>{person.name}</strong></td><td><div className="role-tags">{(person.roles?.length ? person.roles : [person.type]).map((role) => <span className="soft-tag" key={role}>{role}</span>)}</div></td><td>{person.phone || "—"}</td><td className={person.balance > 0 ? "amount-negative" : "muted-cell"}>{person.balance ? formatMoney(person.balance, state.settings.currency) : "بدون مانده"}</td></tr>) : <tr><td colSpan={5}><EmptyState title="هنوز طرف حسابی ندارید" description="با ساختن اولین مخاطب، ثبت عملیات مالی سریع‌تر می‌شود." onAction={() => setOpen(true)} actionLabel="افزودن طرف حساب" /></td></tr>}</tbody></table></div></div>{open && <Dialog title="طرف حساب جدید" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label className="full-field">نام و نام خانوادگی<input autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="مثلاً فروشگاه بهار" /></label><fieldset className="role-fieldset"><legend>نقش‌های طرف حساب <small>(امکان انتخاب چند مورد)</small></legend><div className="checkbox-grid">{PERSON_TYPES.map((role) => <label className="checkbox-option" key={role}><input type="checkbox" checked={form.roles.includes(role)} onChange={() => toggleRole(role)} /><span>{role}</span></label>)}</div></fieldset><label>شماره تماس<input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="اختیاری" /></label><label>شرایط پرداخت پیش‌فرض<select value={form.defaultPaymentRuleId} onChange={(e) => setForm({ ...form, defaultPaymentRuleId: e.target.value })}><option value="">بدون پیش‌فرض</option>{state.paymentRules.map((rule) => <option value={rule.id} key={rule.id}>{rule.name}</option>)}</select></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit">ذخیره طرف حساب</button></div></form></Dialog>}</div>;
}
function Inventory({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [open, setOpen] = useState(false); const [warehouseOpen, setWarehouseOpen] = useState(false); const [warehouseName, setWarehouseName] = useState("");
  const [form, setForm] = useState({ code: "", name: "", unit: "عدد", unit2: "کارتن", conversionRate: "1", warehouseId: state.warehouses[0]?.id || "", stock: "0", minStock: "0", price: "0" });
  function submit(event: React.FormEvent) { event.preventDefault(); if (!form.name.trim()) return; const product = { id: createId("product"), code: form.code.trim() || String(state.products.length + 1).padStart(3, "0"), name: form.name.trim(), unit: form.unit, unit2: form.unit2, conversionRate: Number(form.conversionRate) || 1, warehouseId: form.warehouseId || undefined, stock: Number(form.stock.replace(/[^0-9.-]/g, "")) || 0, minStock: Number(form.minStock.replace(/[^0-9.-]/g, "")) || 0, price: Number(form.price.replace(/[^0-9.-]/g, "")) || 0 }; onSave({ ...state, products: [product, ...state.products] }, "کالای جدید با محل نگهداری ثبت شد"); setOpen(false); }
  return <div className="page-stack page-enter"><PageIntro kicker="کنترل موجودی" title="انبار و کالا" description="کالا را با واحد اول، واحد دوم، نسبت تبدیل و محل نگهداری ثبت کنید." actionLabel="افزودن کالا" onAction={() => setOpen(true)} /><div className="toolbar"><button className="button button-ghost button-small" onClick={() => setWarehouseOpen(true)}>افزودن انبار</button><span className="soft-tag">{formatNumber(state.warehouses.length)} انبار فعال</span></div><div className="inventory-summary"><div><Boxes size={19} /><span>تعداد کالا</span><strong>{formatNumber(state.products.length)}</strong></div><div><WalletCards size={19} /><span>ارزش تقریبی موجودی</span><strong>{formatMoney(state.products.reduce((sum, item) => sum + item.stock * item.price, 0), state.settings.currency)}</strong></div><div><RefreshCw size={19} /><span>نیازمند بررسی</span><strong>{formatNumber(state.products.filter((item) => item.stock <= item.minStock).length)}</strong></div></div><div className="panel table-panel"><div className="panel-heading"><div><span className="section-kicker">دفتر کالا</span><h3>وضعیت فعلی انبار</h3></div><span className="soft-tag">واحد اول / واحد دوم</span></div><div className="table-wrap"><table><thead><tr><th>کد کالا</th><th>نام کالا</th><th>واحدها</th><th>انبار</th><th>موجودی</th><th>قیمت پایه</th><th>وضعیت</th></tr></thead><tbody>{state.products.length ? state.products.map((product) => <tr key={product.id}><td className="muted-cell">{product.code}</td><td><strong>{product.name}</strong></td><td><span className="soft-tag">{product.unit} / {product.unit2 || product.unit} × {formatNumber(product.conversionRate || 1)}</span></td><td>{state.warehouses.find((warehouse) => warehouse.id === product.warehouseId)?.name || "بدون انبار"}</td><td className="amount-cell">{formatNumber(product.stock)}</td><td>{formatMoney(product.price, state.settings.currency)}</td><td><span className={`status-pill ${product.stock <= product.minStock ? "status-warning" : "status-success"}`}>{product.stock <= product.minStock ? "نیاز به تأمین" : "مناسب"}</span></td></tr>) : <tr><td colSpan={7}><EmptyState title="کالایی ثبت نشده" description="پس از ثبت کالا، موجودی و محل نگهداری نمایش داده می‌شود." onAction={() => setOpen(true)} actionLabel="افزودن کالا" /></td></tr>}</tbody></table></div></div>{warehouseOpen && <Dialog title="افزودن انبار جدید" onClose={() => setWarehouseOpen(false)}><form onSubmit={(event) => { event.preventDefault(); if (!warehouseName.trim()) return; onSave({ ...state, warehouses: [{ id: createId("warehouse"), name: warehouseName.trim(), note: "" }, ...state.warehouses] }, "انبار جدید ثبت شد"); setWarehouseName(""); setWarehouseOpen(false); }} className="form-grid"><label className="full-field">نام انبار<input autoFocus value={warehouseName} onChange={(e) => setWarehouseName(e.target.value)} placeholder="مثلاً انبار محصولات تولید" /></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setWarehouseOpen(false)}>انصراف</button><button className="button button-primary" type="submit">ذخیره انبار</button></div></form></Dialog>}{open && <Dialog title="افزودن کالا به انبار" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label>کد کالا<input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} /></label><label>نام کالا<input autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label><label>واحد اول<select value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })}>{UNIT_OPTIONS.map((unit) => <option key={unit}>{unit}</option>)}</select></label><label>واحد دوم<select value={form.unit2} onChange={(e) => setForm({ ...form, unit2: e.target.value })}>{UNIT_OPTIONS.map((unit) => <option key={unit}>{unit}</option>)}</select></label><label>نسبت تبدیل<input inputMode="numeric" value={form.conversionRate} onChange={(e) => setForm({ ...form, conversionRate: e.target.value })} placeholder="مثلاً ۳۶" /></label><label>محل نگهداری<select value={form.warehouseId} onChange={(e) => setForm({ ...form, warehouseId: e.target.value })}>{state.warehouses.map((warehouse) => <option value={warehouse.id} key={warehouse.id}>{warehouse.name}</option>)}</select></label><label>موجودی اولیه<input value={form.stock} onChange={(e) => setForm({ ...form, stock: e.target.value })} /></label><label>حداقل موجودی<input value={form.minStock} onChange={(e) => setForm({ ...form, minStock: e.target.value })} /></label><label>قیمت پایه<input value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره کالا</button></div></form></Dialog>}</div>;
}
function Prices({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [open, setOpen] = useState(false); const [form, setForm] = useState({ productName: "", effectiveDate: todayJalali(), unit: "عدد", price: "", note: "", scope: "عمومی" as "عمومی" | "اختصاصی", partyIds: [] as string[] });
  function submit(event: React.FormEvent) { event.preventDefault(); const price = Number(form.price.replace(/[^0-9.]/g, "")); if (!form.productName.trim() || !price) return; onSave({ ...state, priceHistory: [{ id: createId("price"), productName: form.productName.trim(), scope: form.scope, partyIds: form.scope === "اختصاصی" ? form.partyIds : undefined, effectiveDate: form.effectiveDate, unit: form.unit, price, note: form.note }, ...state.priceHistory] }, "قیمت جدید با دامنه هدف ثبت شد"); setOpen(false); }
  const sorted = [...state.priceHistory].sort((a, b) => b.effectiveDate.localeCompare(a.effectiveDate));
  return <div className="page-stack page-enter"><PageIntro kicker="کنترل قیمت" title="تاریخچه قیمت" description="قیمت می‌تواند عمومی یا برای طرف حساب‌های انتخاب‌شده باشد و در فاکتور قابل override است." actionLabel="ثبت قیمت جدید" onAction={() => setOpen(true)} /><div className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>کالا</th><th>تاریخ اعتبار</th><th>دامنه</th><th>واحد</th><th>قیمت</th><th>توضیحات</th></tr></thead><tbody>{sorted.length ? sorted.map((row) => <tr key={row.id}><td><strong>{row.productName}</strong></td><td>{formatDate(row.effectiveDate)}</td><td><span className="soft-tag">{row.scope}{row.scope === "اختصاصی" ? ` · ${formatNumber(row.partyIds?.length || 0)} طرف حساب` : ""}</span></td><td>{row.unit}</td><td className="amount-cell">{formatMoney(row.price, state.settings.currency)}</td><td>{row.note || "—"}</td></tr>) : <tr><td colSpan={6}><EmptyState title="تاریخچه قیمتی وجود ندارد" description="برای شروع، قیمت معتبر یک کالا را ثبت کنید." onAction={() => setOpen(true)} actionLabel="ثبت قیمت" /></td></tr>}</tbody></table></div></div>{open && <Dialog title="ثبت قیمت جدید" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label>نام کالا<input autoFocus value={form.productName} onChange={(e) => setForm({ ...form, productName: e.target.value })} /></label><label>تاریخ اعتبار<input value={form.effectiveDate} onChange={(e) => setForm({ ...form, effectiveDate: e.target.value })} /></label><label>واحد<select value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })}>{UNIT_OPTIONS.map((unit) => <option key={unit}>{unit}</option>)}</select></label><label>قیمت پایه<input inputMode="numeric" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></label><label>دامنه قیمت<select value={form.scope} onChange={(e) => setForm({ ...form, scope: e.target.value as "عمومی" | "اختصاصی" })}><option>عمومی</option><option>اختصاصی</option></select></label>{form.scope === "اختصاصی" && <label className="full-field">طرف حساب‌های مجاز<select multiple value={form.partyIds} onChange={(e) => setForm({ ...form, partyIds: Array.from(e.target.selectedOptions, (option) => option.value) })}>{state.people.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></label>}<label className="full-field">توضیحات<input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} /></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره قیمت</button></div></form></Dialog>}</div>;
}
function PaymentRules({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: "", dayBasis: "30", graceDays: "0", tiers: [{ maxDays: "30", rate: "0", note: "بدون سود" }] });
  function submit(event: React.FormEvent) { event.preventDefault(); if (!form.name.trim()) return; const tiers = form.tiers.filter((tier) => Number(tier.maxDays) >= 0).map((tier, index) => ({ id: createId(`tier${index}`), maxDays: Number(tier.maxDays), rate: Number(tier.rate) / 100, note: tier.note })); const rule = { id: createId("rule"), name: form.name.trim(), active: true, dayBasis: Number(form.dayBasis) || 30, graceDays: Number(form.graceDays) || 0, tiers }; onSave({ ...state, paymentRules: [rule, ...state.paymentRules] }, "شرایط پرداخت و پله‌های سود ثبت شد"); setOpen(false); setForm({ name: "", dayBasis: "30", graceDays: "0", tiers: [{ maxDays: "30", rate: "0", note: "بدون سود" }] }); }
  function addTier() { setForm({ ...form, tiers: [...form.tiers, { maxDays: "90", rate: "10", note: "" }] }); }
  return <div className="page-stack page-enter"><PageIntro kicker="سیاست تسویه" title="شرایط پرداخت و پله‌های سود" description="قواعد تسویه را یک‌بار تعریف کنید تا محاسبهٔ سود روزشمار شفاف و قابل تغییر بماند." actionLabel="ساخت شرایط پرداخت" onAction={() => setOpen(true)} /><div className="rule-explainer"><div className="mini-icon violet"><Percent size={18} /></div><div><strong>محاسبه بر اساس اصل بدهی و روزهای واقعی</strong><p>هر قاعده می‌تواند مبنای روزشمار و دورهٔ تنفس خودش را داشته باشد. پله‌ها از کمترین روز تا بیشترین روز مرتب می‌شوند.</p></div></div><div className="rules-grid">{state.paymentRules.map((rule) => <div className="panel rule-card" key={rule.id}><div className="rule-head"><div><span className="section-kicker">شرایط تسویه</span><h3>{rule.name}</h3></div><span className={`status-pill ${rule.active ? "status-success" : "status-danger"}`}>{rule.active ? "فعال" : "غیرفعال"}</span></div><div className="rule-meta"><span>مبنای روزشمار <strong>{formatNumber(rule.dayBasis)} روز</strong></span><span>تنفس <strong>{formatNumber(rule.graceDays)} روز</strong></span></div><div className="tier-list">{[...rule.tiers].sort((a, b) => a.maxDays - b.maxDays).map((tier) => <div className="tier-row" key={tier.id}><span className="tier-badge">{tier.maxDays === 9999 ? "∞" : formatNumber(tier.maxDays)} روز</span><strong>{formatNumber(tier.rate * 100)}٪</strong><small>{tier.note || "پلهٔ سود"}</small></div>)}</div></div>)}</div>{open && <Dialog title="ساخت شرایط پرداخت" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label className="full-field">نام شرایط<input autoFocus value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="مثلاً فروش اعتباری مشتریان" /></label><label>مبنای روزشمار<input inputMode="numeric" value={form.dayBasis} onChange={(e) => setForm({ ...form, dayBasis: e.target.value })} /></label><label>روزهای تنفس<input inputMode="numeric" value={form.graceDays} onChange={(e) => setForm({ ...form, graceDays: e.target.value })} /></label><div className="tier-editor"><div className="tier-editor-head"><span>پله‌های سود</span><button type="button" className="text-button" onClick={addTier}><Plus size={14} />افزودن پله</button></div>{form.tiers.map((tier, index) => <div className="tier-edit-row" key={index}><input aria-label="حداکثر روز" inputMode="numeric" value={tier.maxDays} onChange={(e) => setForm({ ...form, tiers: form.tiers.map((item, i) => i === index ? { ...item, maxDays: e.target.value } : item) })} placeholder="تا چند روز" /><input aria-label="درصد سود" inputMode="decimal" value={tier.rate} onChange={(e) => setForm({ ...form, tiers: form.tiers.map((item, i) => i === index ? { ...item, rate: e.target.value } : item) })} placeholder="درصد" /><input aria-label="یادداشت پله" value={tier.note} onChange={(e) => setForm({ ...form, tiers: form.tiers.map((item, i) => i === index ? { ...item, note: e.target.value } : item) })} placeholder="توضیح پله" /></div>)}</div><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره شرایط</button></div></form></Dialog>}</div>;
}

function Checks({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const groups: Array<{ label: CheckStatus; color: string }> = [{ label: "نزد ما", color: "amber" }, { label: "وصول شده", color: "mint" }, { label: "برگشتی", color: "rose" }];
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ number: "", partyId: "", bank: "", receivedDate: todayJalali(), dueDate: todayJalali(), amount: "", paymentRuleId: state.paymentRules.find((item) => item.active)?.id || "" });
  function submit(event: React.FormEvent) { event.preventDefault(); if (!form.number.trim() || !form.amount) return; const check = { id: createId("check"), number: form.number.trim(), partyId: form.partyId || undefined, bank: form.bank, receivedDate: form.receivedDate, dueDate: form.dueDate, amount: Number(form.amount.replace(/[^0-9.-]/g, "")) || 0, paymentRuleId: form.paymentRuleId || undefined, status: "نزد ما" as const }; onSave({ ...state, checks: [check, ...state.checks] }, "چک دریافتی با تاریخ فاکتور ثبت شد"); setOpen(false); setForm({ number: "", partyId: "", bank: "", receivedDate: todayJalali(), dueDate: todayJalali(), amount: "", paymentRuleId: state.paymentRules.find((item) => item.active)?.id || "" }); }
  return <div className="page-stack page-enter"><PageIntro kicker="مدیریت تعهدات" title="چک‌ها" description="چک‌های دریافتی را همراه با تاریخ فاکتور و بستهٔ پرداخت ثبت کنید تا در بستن ماه محاسبه شوند." actionLabel="ثبت چک" onAction={() => setOpen(true)} /><div className="check-cards">{groups.map((group) => <div className="check-card" key={group.label}><span className={`mini-icon ${group.color}`}><FileClock size={17} /></span><span>{group.label}</span><strong>{formatMoney(state.checks.filter((check) => check.status === group.label).reduce((sum, check) => sum + check.amount, 0), state.settings.currency)}</strong><small>{formatNumber(state.checks.filter((check) => check.status === group.label).length)} فقره</small></div>)}</div><div className="panel table-panel"><div className="panel-heading"><div><span className="section-kicker">دفتر چک</span><h3>پیگیری چک‌ها</h3></div><span className="soft-tag">محاسبه بستن ماه آماده</span></div><div className="table-wrap"><table><thead><tr><th>شماره چک</th><th>طرف حساب</th><th>بانک</th><th>تاریخ دریافت</th><th>سررسید</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>{state.checks.length ? state.checks.map((check) => <tr key={check.id}><td><strong>{check.number}</strong></td><td>{personName(state, check.partyId)}</td><td>{check.bank || "—"}</td><td>{formatDate(check.receivedDate)}</td><td>{formatDate(check.dueDate)}</td><td>{formatMoney(check.amount, state.settings.currency)}</td><td><span className={`status-pill ${statusClass(check.status)}`}>{check.status}</span></td></tr>) : <tr><td colSpan={7}><EmptyState title="چکی ثبت نشده" description="چک دریافتی را با تاریخ فاکتور ثبت کنید تا در بستن ماه قابل محاسبه باشد." onAction={() => setOpen(true)} actionLabel="ثبت چک" /></td></tr>}</tbody></table></div></div>{open && <Dialog title="ثبت چک دریافتی" onClose={() => setOpen(false)}><form onSubmit={submit} className="form-grid"><label>شماره چک<input autoFocus value={form.number} onChange={(e) => setForm({ ...form, number: e.target.value })} placeholder="مثلاً ۱۲۳۴۵۶" /></label><label>طرف حساب<select value={form.partyId} onChange={(e) => setForm({ ...form, partyId: e.target.value })}><option value="">بدون طرف حساب</option>{state.people.map((person) => <option value={person.id} key={person.id}>{person.name}</option>)}</select></label><label>تاریخ دریافت چک<input value={form.receivedDate} onChange={(e) => setForm({ ...form, receivedDate: e.target.value })} /></label><label>تاریخ سررسید<input value={form.dueDate} onChange={(e) => setForm({ ...form, dueDate: e.target.value })} /></label><label>مبلغ چک<input inputMode="numeric" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} placeholder="ریال" /></label><label>بانک<input value={form.bank} onChange={(e) => setForm({ ...form, bank: e.target.value })} placeholder="اختیاری" /></label><label className="full-field">بسته شرایط پرداخت<select value={form.paymentRuleId} onChange={(e) => setForm({ ...form, paymentRuleId: e.target.value })}><option value="">انتخاب خودکار بسته فعال</option>{state.paymentRules.map((rule) => <option value={rule.id} key={rule.id}>{rule.name}</option>)}</select></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={() => setOpen(false)}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره چک</button></div></form></Dialog>}</div>;
}
function MonthClose({ state, onSave }: { state: AppState; onSave: (state: AppState, message: string) => void }) {
  const [month, setMonth] = useState(todayJalali().slice(0, 7));
  const [closed, setClosed] = useState(false);
  const received = state.checks.filter((check) => check.status !== "باطل" && check.receivedDate.startsWith(month));
  const rows = received.flatMap((check) => { const rule = state.paymentRules.find((item) => item.id === check.paymentRuleId) || state.paymentRules.find((item) => item.active); const allocations = allocateCheckFIFO(check, state.invoices); const persisted = state.invoices.flatMap((invoice) => invoice.allocations.filter((item) => item.checkId === check.id).map((item) => ({ invoice, allocation: item.amount, remainingAfter: 0 }))); const items = allocations.length ? allocations : persisted.length ? persisted : [{ invoice: undefined, allocation: check.amount, remainingAfter: check.amount }]; return items.map(({ invoice, allocation }) => { const result = calculateLateProfit({ ...check, amount: allocation }, rule, invoice?.date); const personBalance = state.people.find((person) => person.id === check.partyId)?.balance || 0; return { check, invoice, rule, result: { ...result, remaining: Math.max(0, personBalance - allocation) } }; }); });
  const totalCheck = rows.reduce((sum, row) => sum + row.check.amount, 0);
  const totalProfit = rows.reduce((sum, row) => sum + row.result.profit, 0);
  const totalSettled = rows.reduce((sum, row) => sum + row.result.settled, 0);
  const totalRemaining = rows.reduce((sum, row) => sum + row.result.remaining, 0);
  return <div className="page-stack page-enter"><PageIntro kicker="کنترل پایان دوره" title="بستن ماه" description="چک‌های دریافتی را با تاریخ فاکتور، سررسید و بستهٔ شرایط پرداخت تطبیق دهید و سود دیرکرد را مشخص کنید." actionLabel={closed ? "ماه ثبت شده" : "ثبت بستن ماه"} onAction={() => { if (closed) return; onSave({ ...received.reduce((current, check) => applyCheckFIFO(current, check), state), audit: [...state.audit, { id: createId("month-close"), at: new Date().toISOString(), action: "MONTH_CLOSE", note: `بستن ماه ${month} با ${formatNumber(rows.length)} تخصیص FIFO و سود ${formatMoney(totalProfit, state.settings.currency)}` }] }, `بستن ماه ${month} ثبت شد و تخصیص چک‌ها ذخیره شد`); setClosed(true); }} /><div className="close-controls panel"><div><span className="section-kicker">دورهٔ حسابداری</span><strong>ماه مورد بررسی</strong></div><input value={month} onChange={(e) => setMonth(e.target.value)} placeholder="1405/06" /><span className="close-hint">فرمول: مبلغ چک × نرخ پله × روزهای مشمول ÷ مبنای روزشمار</span></div><section className="metric-grid"><MetricCard label="اصل چک‌های دریافتی" value={formatMoney(totalCheck, state.settings.currency)} helper={`${formatNumber(rows.length)} فقره در این دوره`} icon={<FileClock size={20} />} tone="mint" /><MetricCard label="سود دیرکرد" value={formatMoney(totalProfit, state.settings.currency)} helper="طبق شرایط پرداخت فعال" icon={<Percent size={20} />} tone="violet" /><MetricCard label="مبلغ تسویه‌شده" value={formatMoney(totalSettled, state.settings.currency)} helper="اصل چک به‌علاوه سود" icon={<Check size={20} />} tone="indigo" /><MetricCard label="مانده حساب" value={formatMoney(totalRemaining, state.settings.currency)} helper="پس از تخصیص چک‌ها" icon={<WalletCards size={20} />} tone="amber" /></section><div className="panel table-panel"><div className="panel-heading"><div><span className="section-kicker">دفتر تسویه پایان ماه</span><h3>جزئیات چک‌های دریافتی</h3></div><span className={`status-pill ${closed ? "status-success" : "status-warning"}`}>{closed ? "ثبت شده" : "پیش‌نویس"}</span></div><div className="table-wrap"><table><thead><tr><th>شماره چک</th><th>طرف حساب</th><th>فاکتور تخصیص‌یافته</th><th>سررسید</th><th>روز مشمول</th><th>سود دیرکرد</th><th>تسویه</th><th>مانده حساب</th></tr></thead><tbody>{rows.length ? rows.map(({ check, invoice, rule, result }) => <tr key={check.id}><td><strong>{check.number || "بدون شماره"}</strong></td><td>{personName(state, check.partyId)}</td><td>{invoice ? `${invoice.number} · ${formatDate(invoice.date)}` : "در انتظار تخصیص FIFO"}</td><td>{formatDate(check.dueDate)}</td><td><span className="soft-tag">{formatNumber(result.overdueDays)} روز</span></td><td className="amount-cell">{formatMoney(result.profit, state.settings.currency)}<small className="table-subtext">{rule?.name || "بدون بسته"}</small></td><td className="amount-cell">{formatMoney(result.settled, state.settings.currency)}</td><td className="amount-cell">{formatMoney(result.remaining, state.settings.currency)}</td></tr>) : <tr><td colSpan={8}><EmptyState title="چکی برای بستن این ماه وجود ندارد" description="پس از ثبت چک دریافتی با تاریخ فاکتور، جزئیات تسویه اینجا نمایش داده می‌شود." /></td></tr>}</tbody></table></div></div><div className="insight-panel panel"><LockKeyhole size={20} /><div><strong>کنترل قبل از ثبت نهایی</strong><p>این صفحه فعلاً محاسبهٔ پیش‌نویس است. پس از تأیید، نتیجه باید به‌عنوان سند اصلاحی/سود دیرکرد در دفتر عملیات ثبت شود تا قابل گزارش‌گیری و backup باشد.</p></div></div></div>;
}

function Reports({ state, metrics }: { state: AppState; metrics: ReturnType<typeof calculateMetrics> }) { return <div className="page-stack page-enter"><PageIntro kicker="دید مدیریتی" title="گزارش‌ها" description="عددهای کلیدی کارگاه را برای تصمیم‌گیری سریع کنار هم ببینید." actionLabel="خروجی JSON" onAction={() => { const blob = new Blob([exportPayload(state)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "accounting-report.json"; a.click(); URL.revokeObjectURL(url); }} /><div className="report-grid"><div className="panel report-highlight"><span className="section-kicker">خالص گردش نقدی</span><strong>{formatMoney(metrics.balance, state.settings.currency)}</strong><p>بر مبنای دریافت‌ها و پرداخت‌های ثبت‌شده تا امروز.</p><div className="report-line"><span style={{ width: `${Math.min(100, metrics.receipts ? Math.max(10, (metrics.balance / metrics.receipts) * 100) : 10)}%` }} /></div></div><div className="panel report-breakdown"><span className="section-kicker">خلاصهٔ دوره</span><div className="break-row"><span>فروش</span><strong>{formatMoney(metrics.sales, state.settings.currency)}</strong></div><div className="break-row"><span>خرید</span><strong>{formatMoney(metrics.purchases, state.settings.currency)}</strong></div><div className="break-row"><span>دریافت</span><strong className="amount-positive">{formatMoney(metrics.receipts, state.settings.currency)}</strong></div><div className="break-row"><span>پرداخت</span><strong className="amount-negative">{formatMoney(metrics.payments, state.settings.currency)}</strong></div></div></div><div className="panel insight-panel"><div className="mini-icon violet"><ChartNoAxesCombined size={18} /></div><div><strong>گزارش‌های تفصیلی در حال آماده‌سازی هستند</strong><p>ساختار گزارش‌ها از یک هستهٔ دادهٔ واحد تغذیه می‌شود تا ماندهٔ تاریخی، سود روزشمار و موجودی با فرمول‌های پراکنده تکرار نشوند.</p></div></div></div>; }

function BackupPage({ state, onExport, onImport }: { state: AppState; onExport: () => void; onImport: () => void }) { return <div className="page-stack page-enter"><PageIntro kicker="امنیت و تداوم داده" title="پشتیبان و تنظیمات" description="اطلاعات را روی دستگاه نگه دارید و هر زمان خواستید یک نسخهٔ قابل انتقال بسازید." /><div className="backup-grid"><div className="panel backup-main"><div className="backup-hero"><div className="backup-hero-icon"><ShieldCheck size={25} /></div><div><span className="section-kicker">وضعیت ذخیره‌سازی</span><h3>اطلاعات شما محلی و آمادهٔ پشتیبان‌گیری است</h3><p>آخرین تغییر در همین مرورگر ذخیره می‌شود. برای اطمینان، مرتب یک فایل JSON خروجی بگیرید.</p></div></div><div className="backup-actions"><button className="backup-action" onClick={onExport}><span className="backup-action-icon mint"><CloudUpload size={20} /></span><span><strong>ساخت پشتیبان جدید</strong><small>دانلود فایل کامل اطلاعات</small></span><ArrowLeftRight size={16} /></button><button className="backup-action" onClick={onImport}><span className="backup-action-icon violet"><CloudDownload size={20} /></span><span><strong>بازیابی از فایل</strong><small>اعتبارسنجی قبل از جایگزینی</small></span><ArrowLeftRight size={16} /></button></div></div><div className="panel cloud-panel"><div className="cloud-illustration"><Cloud size={28} /></div><span className="section-kicker">مرحلهٔ بعد</span><h3>پشتیبان روی Google Drive</h3><p>اتصال ابری پس از تکمیل مجوز امن Drive اضافه می‌شود؛ فعلاً فایل محلی همیشه در اختیار شماست.</p><span className="coming-tag">به‌زودی · بدون حذف نسخه‌های قبلی</span></div></div><div className="data-health"><div><span className="health-dot" /><strong>داده سالم است</strong><small>{formatNumber(state.people.length + state.products.length + state.transactions.length + state.checks.length)} رکورد قابل بازیابی</small></div><div><FileJson size={18} /><span>نسخهٔ schema: ۱</span></div><div><RefreshCw size={18} /><span>revision: {formatNumber(state.revision)}</span></div></div></div>; }

function PageIntro({ kicker, title, description, actionLabel, onAction }: { kicker: string; title: string; description: string; actionLabel?: string; onAction?: () => void }) { return <section className="page-intro"><div><span className="eyebrow accent-eyebrow">{kicker}</span><h2>{title}</h2><p>{description}</p></div>{actionLabel && onAction && <button className="button button-primary" onClick={onAction}><Plus size={18} />{actionLabel}</button>}</section>; }

function Dialog({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="dialog-backdrop" onMouseDown={onClose}><div className="dialog" onMouseDown={(e) => e.stopPropagation()}><div className="dialog-header"><div><span className="section-kicker">فرم ثبت</span><h3>{title}</h3></div><button className="icon-button" onClick={onClose}><X size={18} /></button></div>{children}</div></div>; }

function QuickAdd({ onClose, people, onSave }: { onClose: () => void; people: AppState["people"]; onSave: (input: { type: TransactionType; amount: number; partyId?: string; note: string; date: string }) => void }) { const [form, setForm] = useState({ type: "دریافت" as TransactionType, amount: "", partyId: "", note: "", date: todayJalali() }); function submit(event: React.FormEvent) { event.preventDefault(); const amount = Number(form.amount.replace(/[^0-9.]/g, "")); if (!amount) return; onSave({ type: form.type, amount, partyId: form.partyId || undefined, note: form.note, date: form.date }); } return <Dialog title="ثبت عملیات جدید" onClose={onClose}><form onSubmit={submit} className="form-grid"><div className="operation-type-grid">{(["دریافت", "پرداخت", "فروش", "خرید", "هزینه", "درآمد"] as TransactionType[]).map((type) => <button type="button" key={type} className={`type-choice ${form.type === type ? "selected" : ""}`} onClick={() => setForm({ ...form, type })}>{type}</button>)}</div><label>مبلغ ({"ریال"})<input autoFocus inputMode="numeric" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} placeholder="مثلاً ۵۰۰۰۰۰۰۰" /></label><label>تاریخ جلالی<input value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></label><label>طرف حساب<select value={form.partyId} onChange={(e) => setForm({ ...form, partyId: e.target.value })}><option value="">بدون طرف حساب</option>{people.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></label><label>توضیحات<input value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} placeholder="اختیاری" /></label><div className="form-actions"><button type="button" className="button button-ghost" onClick={onClose}>انصراف</button><button className="button button-primary" type="submit"><Check size={17} />ذخیره عملیات</button></div></form></Dialog>; }
